def main() -> None:
    for rel, blob in FILES.items():
        path = ROOT / rel
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_bytes(base64.b64decode("".join(blob.split())))
        print("wrote", rel)
    print("done", len(FILES))

if __name__ == "__main__":
    main()
